import type { DomainFlowsheet } from '../domain/flowsheet'
import type { MaterialState } from '../domain/stream'
import type { OperationContext } from '../operations/types'
import {
  TEACHING_BINARY_FLUID,
  createTeachingBinaryMaterialState,
} from '../properties/teachingBinaryFluid'

/**
 * Independent fixture values.
 *
 * These are deliberately written as literals instead of being generated by
 * the unit-conversion functions under test:
 *   6 t/h  = 6  * 1000 / 3600 = 1.6666666666666667 kg/s
 *   12 t/h = 12 * 1000 / 3600 = 3.3333333333333335 kg/s
 */
export const MASS_FLOW_6_TPH_KG_S = 1.6666666666666667
export const MASS_FLOW_12_TPH_KG_S = 3.3333333333333335
export const PRESSURE_2_8_BAR_PA = 280000
export const PRESSURE_2_6_BAR_PA = 260000

export const FEED_A: MaterialState = createTeachingBinaryMaterialState({
  massFlowKgS: MASS_FLOW_6_TPH_KG_S,
  temperatureK: 298.15,
  pressurePa: PRESSURE_2_8_BAR_PA,
  massFractionA: 0.95,
})

export const FEED_B: MaterialState = createTeachingBinaryMaterialState({
  massFlowKgS: MASS_FLOW_6_TPH_KG_S,
  temperatureK: 338.15,
  pressurePa: PRESSURE_2_6_BAR_PA,
  massFractionA: 0.15,
})

export const MIXED_45C: MaterialState = createTeachingBinaryMaterialState({
  massFlowKgS: MASS_FLOW_12_TPH_KG_S,
  temperatureK: 318.15,
  pressurePa: PRESSURE_2_6_BAR_PA,
  massFractionA: 0.55,
})

export const MIXER_CONTEXT: OperationContext = {
  nodeId: 'mixer-101',
  tag: 'MX-101',
  propertyPackage: TEACHING_BINARY_FLUID,
}

export const HEATER_CONTEXT: OperationContext = {
  nodeId: 'heater-101',
  tag: 'HX-101',
  propertyPackage: TEACHING_BINARY_FLUID,
}

export const COOLER_CONTEXT: OperationContext = {
  nodeId: 'cooler-101',
  tag: 'CL-101',
  propertyPackage: TEACHING_BINARY_FLUID,
}

export function makeFullFlowsheet(): DomainFlowsheet {
  return {
    nodes: [
      {
        id: 'feed-a',
        tag: 'F-101',
        kind: 'stream',
        role: 'feed',
        state: FEED_A,
      },
      {
        id: 'feed-b',
        tag: 'F-102',
        kind: 'stream',
        role: 'feed',
        state: FEED_B,
      },
      { id: 'mixer-101', tag: 'MX-101', kind: 'mixer' },
      {
        id: 'heater-101',
        tag: 'HX-101',
        kind: 'heater',
        targetTemperatureK: 358.15,
      },
      { id: 'product-101', tag: 'PR-101', kind: 'stream', role: 'product' },
    ],
    edges: [
      {
        id: 's-101',
        tag: 'S-101',
        sourceNodeId: 'feed-a',
        targetNodeId: 'mixer-101',
      },
      {
        id: 's-102',
        tag: 'S-102',
        sourceNodeId: 'feed-b',
        targetNodeId: 'mixer-101',
      },
      {
        id: 's-103',
        tag: 'S-103',
        sourceNodeId: 'mixer-101',
        targetNodeId: 'heater-101',
      },
      {
        id: 's-104',
        tag: 'S-104',
        sourceNodeId: 'heater-101',
        targetNodeId: 'product-101',
      },
    ],
  }
}
